(function () {
  if (document.getElementById("vp")) return;   // the page carries its own markup
  var host = document.createElement("div");
  host.innerHTML = "<div id=\"vp\"><div id=\"scroller\">\n\n  <header class=\"lab-hero\">\n    <div class=\"wrap\">\n      <p class=\"mono eyebrow rv\">Component lab &middot; 06 &nbsp;/&nbsp; Backgrounds</p>\n      <h1 class=\"rv\">One page, six <span class=\"it\">rooms</span>.</h1>\n      <p class=\"lede rv\">Most sites have one background and light it differently. This is the other\n        approach: a sequence of grounds a reader travels between, where each one arrives over the\n        last in its own way &mdash; covered, wiped, opened through, folded up or pushed sideways.\n        Every transition is scrubbed from the scrollbar, so all six run backwards as cleanly as\n        forwards.</p>\n\n      <nav class=\"lab-tabs rv\" style=\"margin-top:34px\" aria-label=\"Component lab\">\n        <a class=\"lab-tab\" href=\"/media\"><i></i>Media</a>\n        <a class=\"lab-tab\" href=\"/cards\"><i></i>Cards</a>\n        <a class=\"lab-tab\" href=\"/testimonials\"><i></i>Testimonials</a>\n        <a class=\"lab-tab\" href=\"/cta\"><i></i>Call to action</a>\n        <a class=\"lab-tab\" href=\"/team\"><i></i>Team</a>\n        <a class=\"lab-tab\" href=\"/backgrounds\" aria-current=\"page\"><i></i>Backgrounds</a>\n      </nav>\n\n      <div class=\"lab-figs rv\">\n        <div class=\"lab-fig\"><b>17</b><em>Procedural grounds</em></div>\n        <div class=\"lab-fig\"><b>06</b><em>Scene transitions</em></div>\n        <div class=\"lab-fig\"><b>0</b><em>Image files</em></div>\n        <div class=\"lab-fig\"><b>2</b><em>Canvases drawn at once</em></div>\n      </div>\n    </div>\n  </header>\n\n  <!-- ============ THE SCENE RIG ============ -->\n  <div class=\"scenes\" data-scenes>\n    <div class=\"scenes-pin\">\n\n      <!-- 01 — AURORA -->\n      <section class=\"scene\" data-enter=\"cover\" data-exit=\"recede\" aria-label=\"Aurora\">\n        <div class=\"scene-body\">\n          <canvas class=\"scene-bg\" data-bg=\"aurora\" data-density=\"1.1\" data-speed=\"1\" data-alpha=\"1\" data-seed=\"11\" aria-hidden=\"true\"></canvas>\n          <span class=\"scene-tint\" aria-hidden=\"true\"></span>\n          <div class=\"scene-in\"><div class=\"wrap\"><div class=\"scene-copy\">\n            <span class=\"mono k\">Ground 01 &middot; Aurora</span>\n            <h2>Light with <span class=\"it\">no edges</span>.</h2>\n            <p>Five ribbons bent across the frame on offset loops, rendered at 55% of device\n              resolution and blurred &mdash; because an aurora has no detail to lose, and the blur\n              is the whole effect. It screens onto the dark ground and multiplies onto paper, so\n              neither theme washes it out.</p>\n            <ul class=\"scene-spec\">\n              <li>Ribbons <b>5</b></li><li>Render scale <b>0.55&times;</b></li>\n              <li>Canvas blur</li><li>Blend flips with theme</li>\n            </ul>\n          </div></div></div>\n        </div>\n      </section>\n\n      <!-- 02 — TERRAIN -->\n      <section class=\"scene\" data-enter=\"cover\" data-exit=\"hold\" aria-label=\"Terrain\">\n        <div class=\"scene-body\">\n          <canvas class=\"scene-bg\" data-bg=\"terrain\" data-density=\"1\" data-speed=\"1\" data-alpha=\".95\" aria-hidden=\"true\"></canvas>\n          <span class=\"scene-tint\" aria-hidden=\"true\"></span>\n          <div class=\"scene-in\"><div class=\"wrap\"><div class=\"scene-copy\">\n            <span class=\"mono k\">Ground 02 &middot; Terrain</span>\n            <h2>A landscape, running at you.</h2>\n            <p>Rows spaced by one-over-z rather than evenly, which is the entire difference between\n              perspective and a stack of wavy lines. The height field is three summed sines, so the\n              ridges never repeat inside a viewing.</p>\n            <ul class=\"scene-spec\">\n              <li>Rows <b>24</b></li><li>Perspective divide</li>\n              <li>Horizon at <b>34%</b></li><li>Continuous scroll</li>\n            </ul>\n          </div></div></div>\n        </div>\n        <p class=\"scene-tag\" aria-hidden=\"true\"><i></i>Arrived by <b>cover</b></p>\n      </section>\n\n      <!-- 03 — PLASMA -->\n      <section class=\"scene\" data-enter=\"curtain\" data-exit=\"recede\" aria-label=\"Plasma\">\n        <div class=\"scene-body\">\n          <canvas class=\"scene-bg\" data-bg=\"plasma\" data-density=\"1\" data-speed=\"1\" data-alpha=\"1\" aria-hidden=\"true\"></canvas>\n          <span class=\"scene-tint\" aria-hidden=\"true\"></span>\n          <div class=\"scene-in\"><div class=\"wrap\"><div class=\"scene-copy\">\n            <span class=\"mono k\">Ground 03 &middot; Plasma</span>\n            <h2>Interference, warped.</h2>\n            <p>Four sine fields sampled through a domain warp, computed at a ninth of the frame and\n              scaled back up. That turns a full-resolution pixel loop into a twenty-thousand pixel\n              one &mdash; a shader's look without a shader's budget.</p>\n            <ul class=\"scene-spec\">\n              <li>Per-pixel</li><li>Divisor <b>9</b></li>\n              <li>Domain warp</li><li>~20k px / frame</li>\n            </ul>\n          </div></div></div>\n        </div>\n        <p class=\"scene-tag\" aria-hidden=\"true\"><i></i>Arrived by <b>curtain</b></p>\n      </section>\n\n      <!-- 04 — CIRCUIT -->\n      <section class=\"scene\" data-enter=\"iris\" data-exit=\"rise\" aria-label=\"Circuit\">\n        <div class=\"scene-body\">\n          <canvas class=\"scene-bg\" data-bg=\"circuit\" data-density=\"1.2\" data-speed=\"1\" data-alpha=\".95\" aria-hidden=\"true\"></canvas>\n          <span class=\"scene-tint\" aria-hidden=\"true\"></span>\n          <div class=\"scene-in\"><div class=\"wrap\"><div class=\"scene-copy\">\n            <span class=\"mono k\">Ground 04 &middot; Circuit</span>\n            <h2>Traces, and something travelling them.</h2>\n            <p>Manhattan paths snapped to a grid, each terminating in a pad, each carrying a pulse\n              that walks the segments at a constant speed rather than a constant parameter &mdash;\n              so a long leg does not go faster than a short one.</p>\n            <ul class=\"scene-spec\">\n              <li>Traces <b>26</b></li><li>Arc-length pulse</li>\n              <li>Grid-snapped</li><li>Radial glow</li>\n            </ul>\n          </div></div></div>\n        </div>\n        <p class=\"scene-tag\" aria-hidden=\"true\"><i></i>Arrived by <b>iris</b></p>\n      </section>\n\n      <!-- 05 — CAUSTICS -->\n      <section class=\"scene\" data-enter=\"fold\" data-exit=\"slide\" aria-label=\"Caustics\">\n        <div class=\"scene-body\">\n          <canvas class=\"scene-bg\" data-bg=\"caustics\" data-density=\"1\" data-speed=\"1\" data-alpha=\".9\" aria-hidden=\"true\"></canvas>\n          <span class=\"scene-tint\" aria-hidden=\"true\"></span>\n          <div class=\"scene-in\"><div class=\"wrap\"><div class=\"scene-copy\">\n            <span class=\"mono k\">Ground 05 &middot; Caustics</span>\n            <h2>The same maths, a harder curve.</h2>\n            <p>Identical machinery to the plasma, with the transfer curve raised to the seventh\n              power. That is all it takes to turn broad interference into the thin bright filaments\n              light makes on the floor of a pool.</p>\n            <ul class=\"scene-spec\">\n              <li>Shared engine</li><li>Divisor <b>7</b></li>\n              <li>Transfer <b>x&#8311;</b></li><li>Filament falloff</li>\n            </ul>\n          </div></div></div>\n        </div>\n        <p class=\"scene-tag\" aria-hidden=\"true\"><i></i>Arrived by <b>fold</b></p>\n      </section>\n\n      <!-- 06 — ORBITS -->\n      <section class=\"scene\" data-enter=\"slide\" data-exit=\"recede\" aria-label=\"Orbits\">\n        <div class=\"scene-body\">\n          <canvas class=\"scene-bg\" data-bg=\"orbits\" data-density=\"1.1\" data-speed=\"1\" data-alpha=\".95\" aria-hidden=\"true\"></canvas>\n          <span class=\"scene-tint\" aria-hidden=\"true\"></span>\n          <div class=\"scene-in\"><div class=\"wrap\"><div class=\"scene-copy\">\n            <span class=\"mono k\">Ground 06 &middot; Orbits</span>\n            <h2>Paths, and the things on them.</h2>\n            <p>Eight rotated ellipses with a body on each. The trail is an arc of the same ellipse\n              rather than a fading line, so it sits exactly on the path instead of near it &mdash;\n              which is the detail that stops it reading as a screensaver.</p>\n            <ul class=\"scene-spec\">\n              <li>Orbits <b>8</b></li><li>Rotated ellipses</li>\n              <li>Trail on-path</li><li>Both directions</li>\n            </ul>\n          </div></div></div>\n        </div>\n        <p class=\"scene-tag\" aria-hidden=\"true\"><i></i>Arrived by <b>slide</b></p>\n      </section>\n\n      <div class=\"scenes-rail\" aria-hidden=\"true\">\n        <span class=\"on\"></span><span></span><span></span><span></span><span></span><span></span>\n      </div>\n    </div>\n  </div>\n\n  <!-- ============ PARALLAX BAND ============ -->\n  <section class=\"lab-sec\" id=\"parallax\" style=\"padding-bottom:0\">\n    <div class=\"wrap\">\n      <div class=\"lab-head\">\n        <div>\n          <p class=\"mono eyebrow rv\">At section scale</p>\n          <h2 class=\"display\" data-split=\"rise\">Three grounds, three rates.</h2>\n        </div>\n        <div>\n          <p class=\"lede rv\">Not every background needs a whole screen. The same fields stack\n            inside one band and travel at different rates against the scroll, which buys depth\n            without taking the page hostage.</p>\n          <ul class=\"spec mono rv\">\n            <li>Three layers</li><li>-6% / -18% / -34%</li>\n            <li>One scrubbed value</li><li>Section height, not viewport</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"plx\" data-band data-ramp=\"0.9\">\n      <div class=\"plx-l\"><canvas data-bg=\"dust\" data-density=\".7\" data-speed=\".6\" data-alpha=\".7\" data-seed=\"3\" aria-hidden=\"true\"></canvas></div>\n      <div class=\"plx-l\"><canvas data-bg=\"contour\" data-density=\".8\" data-speed=\".8\" data-alpha=\".8\" aria-hidden=\"true\"></canvas></div>\n      <div class=\"plx-l\"><canvas data-bg=\"mesh\" data-density=\"1\" data-speed=\"1.1\" data-alpha=\".9\" data-seed=\"19\" aria-hidden=\"true\"></canvas></div>\n      <span class=\"plx-veil\" aria-hidden=\"true\"></span>\n      <div class=\"plx-in\"><div class=\"inner\">\n        <h3>Depth is a rate, not a shadow.</h3>\n        <p>Three fields at three speeds read as three distances. Nothing here is blurred and\n          nothing is scaled &mdash; only the rate differs.</p>\n      </div></div>\n    </div>\n  </section>\n\n  <!-- ============ FIELD INDEX ============ -->\n  <section class=\"lab-sec\" id=\"index\">\n    <div class=\"wrap\">\n      <div class=\"lab-head\">\n        <div>\n          <p class=\"mono eyebrow rv\">The set</p>\n          <h2 class=\"display\" data-split=\"rise\">Seventeen grounds.</h2>\n        </div>\n        <div>\n          <p class=\"lede rv\">Every field the lab can draw, at thumbnail size. One engine; a canvas\n            declares which field it is and how hard to run it. Each reads its tint from its own\n            host element, so a field inside an inverted island keeps the bright accent while the\n            page around it flips.</p>\n          <ul class=\"spec mono rv\">\n            <li>data-bg</li><li>data-speed</li><li>data-density</li>\n            <li>data-alpha</li><li>data-seed</li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"fgrid rv\">\n        <div class=\"fcell\"><canvas data-bg=\"starfield\" data-density=\"1.4\" aria-hidden=\"true\"></canvas><em>01</em><b>starfield</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"rings\" data-speed=\"1.4\" aria-hidden=\"true\"></canvas><em>02</em><b>rings</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"streaks\" data-density=\"1.6\" data-speed=\"1.6\" aria-hidden=\"true\"></canvas><em>03</em><b>streaks</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"scan\" data-speed=\"1.3\" aria-hidden=\"true\"></canvas><em>04</em><b>scan</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"grid3d\" data-speed=\"1.4\" aria-hidden=\"true\"></canvas><em>05</em><b>grid3d</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"hex\" data-size=\"16\" data-alpha=\"1.5\" aria-hidden=\"true\"></canvas><em>06</em><b>hex</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"mesh\" data-density=\"1.6\" aria-hidden=\"true\"></canvas><em>07</em><b>mesh</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"contour\" data-density=\"1.2\" aria-hidden=\"true\"></canvas><em>08</em><b>contour</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"dust\" data-density=\"1.8\" aria-hidden=\"true\"></canvas><em>09</em><b>dust</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"moire\" data-density=\"1.2\" aria-hidden=\"true\"></canvas><em>10</em><b>moire</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"ledger\" data-density=\"1.4\" aria-hidden=\"true\"></canvas><em>11</em><b>ledger</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"aurora\" data-density=\"1.4\" data-speed=\"1.4\" aria-hidden=\"true\"></canvas><em>12</em><b>aurora</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"terrain\" data-density=\"1.2\" data-speed=\"1.4\" aria-hidden=\"true\"></canvas><em>13</em><b>terrain</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"plasma\" data-speed=\"1.6\" aria-hidden=\"true\"></canvas><em>14</em><b>plasma</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"caustics\" data-speed=\"1.5\" aria-hidden=\"true\"></canvas><em>15</em><b>caustics</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"circuit\" data-density=\"1.6\" data-speed=\"1.5\" aria-hidden=\"true\"></canvas><em>16</em><b>circuit</b></div>\n        <div class=\"fcell\"><canvas data-bg=\"orbits\" data-density=\"1.3\" data-speed=\"1.6\" aria-hidden=\"true\"></canvas><em>17</em><b>orbits</b></div>\n      </div>\n\n      <p class=\"mono rv\" style=\"color:var(--paper-3);margin-top:26px;text-transform:none;letter-spacing:.06em;font-size:.66rem\">\n        Every field sleeps when it leaves the screen and when the tab hides. Inside the scene rig\n        above, only the two scenes actually in play are drawn &mdash; the other four hold their last\n        frame behind <b style=\"color:var(--gold)\">visibility: hidden</b>. Under\n        <b style=\"color:var(--gold)\">prefers-reduced-motion</b> each paints a single static frame\n        and the rig becomes six ordinary sections.\n      </p>\n    </div>\n  </section>\n\n  <section class=\"lab-sec\" id=\"next\">\n    <div class=\"wrap\" style=\"text-align:center\">\n      <p class=\"mono eyebrow rv\" style=\"justify-content:center\">Back to the components</p>\n      <h2 class=\"display rv\" style=\"margin-bottom:26px\">Grounds are half of it.</h2>\n      <p class=\"lede rv\" style=\"margin:0 auto 32px\">The other half is what sits on top. Nineteen\n        components across five pages, all on the same token set.</p>\n      <div class=\"rv\" style=\"display:flex;gap:12px;justify-content:center;flex-wrap:wrap\">\n        <a class=\"btn solid\" href=\"/media\" data-mag><span class=\"btn-l\">Media</span><span class=\"arw\">&#8594;</span></a>\n        <a class=\"btn\" href=\"/\" data-mag><span class=\"btn-l\">The homepage</span></a>\n      </div>\n    </div>\n  </section>\n\n</div></div>\n<div id=\"spacer\" aria-hidden=\"true\"></div>\n";
  var frag = document.createDocumentFragment();
  while (host.firstChild) frag.appendChild(host.firstChild);
  document.body.insertBefore(frag, document.body.firstChild);
})();
